// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/admin/geo/tree", wrapper.GetAdminGeoTree)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/admin/geo/districts", wrapper.ListDistricts)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/geo/districts", wrapper.CreateDistrict)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/v1/admin/geo/districts/{district_id}", wrapper.UpdateDistrict)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/admin/geo/mandals", wrapper.ListMandals)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/geo/mandals", wrapper.CreateMandal)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/v1/admin/geo/mandals/{mandal_id}", wrapper.UpdateMandal)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/admin/geo/villages", wrapper.ListVillages)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/geo/villages", wrapper.CreateVillage)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/admin/geo/villages/{village_id}", wrapper.GetVillage)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/v1/admin/geo/villages/{village_id}", wrapper.UpdateVillage)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/geo/village-imports", wrapper.ImportVillages)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/admin/allocations", wrapper.ListAllocations)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/allocations", wrapper.CreateAllocation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/allocations/{allocation_id}/end", wrapper.EndAllocation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/admin/allocations/handover", wrapper.HandoverAllocations)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/farmer/villages", wrapper.SearchFarmerVillages)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/farmer/geo/tree", wrapper.GetFarmerGeoTree)
	})

	return r
}

