// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAllocations List FA allocations
	// (GET /v1/admin/allocations)
	ListAllocations(ctx context.Context, request ListAllocationsRequestObject) (ListAllocationsResponseObject, error)
	// CreateAllocation Allocate an FA to a village, mandal or district
	// (POST /v1/admin/allocations)
	CreateAllocation(ctx context.Context, request CreateAllocationRequestObject) (CreateAllocationResponseObject, error)
	// HandoverAllocations Move all of one FA's current allocations to another FA
	// (POST /v1/admin/allocations/handover)
	HandoverAllocations(ctx context.Context, request HandoverAllocationsRequestObject) (HandoverAllocationsResponseObject, error)
	// EndAllocation End an allocation now
	// (POST /v1/admin/allocations/{allocation_id}/end)
	EndAllocation(ctx context.Context, request EndAllocationRequestObject) (EndAllocationResponseObject, error)
	// ListDistricts List districts
	// (GET /v1/admin/geo/districts)
	ListDistricts(ctx context.Context, request ListDistrictsRequestObject) (ListDistrictsResponseObject, error)
	// CreateDistrict Add a district
	// (POST /v1/admin/geo/districts)
	CreateDistrict(ctx context.Context, request CreateDistrictRequestObject) (CreateDistrictResponseObject, error)
	// UpdateDistrict Edit a district
	// (PATCH /v1/admin/geo/districts/{district_id})
	UpdateDistrict(ctx context.Context, request UpdateDistrictRequestObject) (UpdateDistrictResponseObject, error)
	// ListMandals List mandals
	// (GET /v1/admin/geo/mandals)
	ListMandals(ctx context.Context, request ListMandalsRequestObject) (ListMandalsResponseObject, error)
	// CreateMandal Add a mandal to a district
	// (POST /v1/admin/geo/mandals)
	CreateMandal(ctx context.Context, request CreateMandalRequestObject) (CreateMandalResponseObject, error)
	// UpdateMandal Edit a mandal
	// (PATCH /v1/admin/geo/mandals/{mandal_id})
	UpdateMandal(ctx context.Context, request UpdateMandalRequestObject) (UpdateMandalResponseObject, error)
	// GetAdminGeoTree District and mandal tree with village counts
	// (GET /v1/admin/geo/tree)
	GetAdminGeoTree(ctx context.Context, request GetAdminGeoTreeRequestObject) (GetAdminGeoTreeResponseObject, error)
	// ImportVillages Bulk import villages from CSV
	// (POST /v1/admin/geo/village-imports)
	ImportVillages(ctx context.Context, request ImportVillagesRequestObject) (ImportVillagesResponseObject, error)
	// ListVillages List or search villages
	// (GET /v1/admin/geo/villages)
	ListVillages(ctx context.Context, request ListVillagesRequestObject) (ListVillagesResponseObject, error)
	// CreateVillage Add a village to a mandal
	// (POST /v1/admin/geo/villages)
	CreateVillage(ctx context.Context, request CreateVillageRequestObject) (CreateVillageResponseObject, error)
	// GetVillage One village with its mandal and district
	// (GET /v1/admin/geo/villages/{village_id})
	GetVillage(ctx context.Context, request GetVillageRequestObject) (GetVillageResponseObject, error)
	// UpdateVillage Edit a village
	// (PATCH /v1/admin/geo/villages/{village_id})
	UpdateVillage(ctx context.Context, request UpdateVillageRequestObject) (UpdateVillageResponseObject, error)
	// GetFarmerGeoTree District and mandal tree for the village picker
	// (GET /v1/farmer/geo/tree)
	GetFarmerGeoTree(ctx context.Context, request GetFarmerGeoTreeRequestObject) (GetFarmerGeoTreeResponseObject, error)
	// SearchFarmerVillages Pick your village (farmer self sign-up)
	// (GET /v1/farmer/villages)
	SearchFarmerVillages(ctx context.Context, request SearchFarmerVillagesRequestObject) (SearchFarmerVillagesResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

